#!/usr/bin/env python3
"""Hanauta · Holographic Yuna — standalone PyQt6 widget.
GUIA RÁPIDO
• Dependências: PyQt6 >= 6.6, numpy, opencv-python-headless.
• Configurar > Demonstração: testa os movimentos sem produzir fala.
• Configurar > Abrir áudio WAV: reproduz a voz e anima a boca pelo áudio.
• Para lipsync por fonemas, carregue depois o JSON de visemas do Rhubarb
  (ou adapte os eventos do seu TTS para A–H/X). O arquivo NÃO infere fonemas.
• Microfone, anexos, captura, histórico e conversa emitem sinais para o app;
  o host precisa conectá-los aos serviços existentes.
• O retrato está embutido; não é preciso baixar nenhum modelo ou asset.
• A imagem é uma adaptação da referência Holographic Yuna feita por imagegen.
  Prompt: preservar o rosto e as partículas lilás, remover a interface,
  retrato frontal sobre carvão, olhos e boca desobstruídos para deformação.

Dependencies: PyQt6 >= 6.6, numpy, opencv-python-headless.
Run: python hanauta_voice_yuna.py [--wav speech.wav] [--cues speech.json]

Artwork embedded; no API, network, microphone recording or TTS is enabled.
Configurar > Abrir áudio loads PCM WAV (16 bit, mono/stereo, <=120 seconds).
Audio envelope controls jaw opening; this is NOT phoneme recognition.
For timed visemes use Rhubarb-style JSON {"mouthCues": [{"start":0.0,
"end":0.2,"value":"A"}, ...]}; A-H/X mapped to 2D mouth deformations.
The deformation cannot reconstruct hidden teeth or new head viewpoints.

Integrate VoiceView in the existing chat container. Connect action_requested
(str), microphone_changed(bool), context_changed(bool). Methods (GUI thread):
set_transcripts(user, assistant), play_wav(path, cues=None), set_visemes(list),
set_voice_frame(level, viseme=None) for externally played TTS chunks, stop().
set_voice_frame must follow the PLAYBACK clock, not synthesis arrival time;
feed at ~30Hz, level in [0,1]. Missing frames expire after 250ms.
Use queued Qt signals when calling from a worker. pause/mute/microphone
requests must also be applied to your external TTS/STT backend.
Demo motion is explicitly silent. Real audio is loaded asynchronously.

Technique: local inverse Gaussian image warping, amplitude smoothing,
viseme coarticulation, independent eye blinks, slow head sway and particles.
UI is native Qt, each icon is painted and springs/rotates on activation.
No generative video model / forced aligner is bundled.
"""
import sys, math, time, json, base64, wave, argparse
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import numpy as np
import cv2
from PyQt6.QtCore import Qt, QTimer, QRectF, QPointF, QUrl, QVariantAnimation, QEasingCurve, pyqtSignal
from PyQt6.QtGui import QColor, QPainter, QPen, QPainterPath, QImage, QFont
from PyQt6.QtWidgets import (QApplication, QWidget, QFrame, QLabel, QVBoxLayout, QHBoxLayout,
    QAbstractButton, QSizePolicy, QFileDialog, QMenu, QMessageBox)
from PyQt6.QtMultimedia import QMediaPlayer, QAudioOutput

ART = ''
BG='#141218'; PANEL='#211e27'; RAISED='#302b3a'; ACCENT='#d0bcff'; INK='#281451'

def icon(p, kind):
    """24x24 vector paths, independent of OS icon fonts."""
    def line(a,b,c,d): p.drawLine(QPointF(a,b),QPointF(c,d))
    def rect(x,y,w,h,r=2): p.drawRoundedRect(QRectF(x,y,w,h),r,r)
    if kind=='mic':
        rect(9,3,6,12,3); p.drawArc(QRectF(5,6,14,14),180*16,180*16); line(12,20,12,23)
    elif kind=='wave':
        for i,h in enumerate([5,12,20,12,5]): line(4+i*4,12-h/2,4+i*4,12+h/2)
    elif kind=='close': line(5,5,19,19); line(19,5,5,19)
    elif kind=='clock': p.drawEllipse(QRectF(3,3,18,18)); line(12,6,12,12); line(12,12,16,14)
    elif kind=='settings':
        p.drawEllipse(QRectF(7,7,10,10))
        for a in range(0,360,45):
            x,y=math.cos(math.radians(a)),math.sin(math.radians(a)); line(12+x*8,12+y*8,12+x*10,12+y*10)
    elif kind=='pause': line(8,5,8,19); line(16,5,16,19)
    elif kind=='play': line(8,4,20,12); line(20,12,8,20); line(8,20,8,4)
    elif kind=='screen': rect(2,3,20,14); line(12,17,12,22); line(7,22,17,22)
    elif kind=='keyboard':
        rect(1,5,22,14)
        for y in (9,13):
            for x in (5,9,13,17): line(x,y,x+1,y)
        line(8,16,16,16)
    elif kind=='chat': rect(2,3,20,15,4); line(5,18,5,22); line(5,22,10,18)
    elif kind=='attach':
        rect(3,3,18,18); p.drawEllipse(QRectF(6,6,3,3)); line(4,18,11,12); line(11,12,20,18)
    elif kind=='phone':
        p.drawArc(QRectF(3,7,18,13),0,180*16); line(3,13,3,18); line(21,13,21,18)
    elif kind=='speaker':
        line(3,10,7,10); line(7,10,12,5); line(12,5,12,19); line(12,19,7,14); line(7,14,3,14); line(3,14,3,10)
        p.drawArc(QRectF(10,6,10,12),-70*16,140*16)
    elif kind=='person': p.drawEllipse(QRectF(8,2,8,8)); p.drawArc(QRectF(3,12,18,15),0,180*16)
    else: line(6,9,12,15); line(12,15,18,9)

class MotionButton(QAbstractButton):
    def __init__(self, glyph, text='', primary=False, danger=False, parent=None):
        super().__init__(parent); self.glyph=glyph; self.caption=text; self.primary=primary; self.danger=danger
        self.phase=1.; self.setText(text or glyph); self.setAccessibleName(text or glyph)
        self.setToolTip(text or glyph); self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus); self.setMinimumSize(48,48)
        self.setSizePolicy(QSizePolicy.Policy.Expanding,QSizePolicy.Policy.Fixed)
        self.setFixedHeight(70 if text else 48)
        self.anim=QVariantAnimation(self); self.anim.setDuration(440); self.anim.setStartValue(0.); self.anim.setEndValue(1.)
        self.anim.valueChanged.connect(self.animate); self.clicked.connect(self.bounce)
    def bounce(self): self.anim.stop(); self.anim.start()
    def animate(self,v): self.phase=float(v); self.update()
    def paintEvent(self,e):
        p=QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r=QRectF(self.rect()).adjusted(1,1,-1,-1)
        p.setPen(QPen(QColor(ACCENT),1) if self.hasFocus() else Qt.PenStyle.NoPen)
        p.setBrush(QColor(ACCENT if self.primary or self.isChecked() else ('#39323f' if self.underMouse() else RAISED)))
        p.drawRoundedRect(r,22,22)
        if self.phase<1:
            p.save(); clip=QPainterPath(); clip.addRoundedRect(r,22,22); p.setClipPath(clip)
            p.setBrush(QColor(230,216,255,int(48*(1-self.phase)))); p.drawEllipse(r.center(),self.width()*self.phase,self.width()*self.phase); p.restore()
        p.save(); p.translate(self.width()/2,24 if self.caption else self.height()/2)
        pulse=math.sin(self.phase*math.pi*3)*(1-self.phase)
        p.rotate(10*pulse); p.scale(1+.13*pulse,1+.13*pulse); p.translate(-12,-12)
        col=INK if self.primary or self.isChecked() else ('#ff99b2' if self.danger else ACCENT)
        p.setBrush(Qt.BrushStyle.NoBrush); p.setPen(QPen(QColor(col),1.8,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap,Qt.PenJoinStyle.RoundJoin)); icon(p,self.glyph); p.restore()
        if self.caption:
            p.setPen(QColor(col)); p.setFont(QFont('Sans Serif',10)); p.drawText(QRectF(0,44,self.width(),22),Qt.AlignmentFlag.AlignCenter,self.caption)

# Closure / horizontal mouth scale. Rhubarb A=MBP, B=consonants, C=EH,
# D=AA, E=AO, F=UW, G=FV, H=L, X=rest. Not a semantic classifier.
VISEMES={'A':(0.,1.),'B':(.22,1.08),'C':(.5,1.12),'D':(1.,1.05),
         'E':(.65,.83),'F':(.3,.75),'G':(.12,1.02),'H':(.38,1.),'X':(0.,1.)}

class FaceCanvas(QWidget):
    def __init__(self,parent=None):
        super().__init__(parent); self.setMinimumHeight(210)
        raw=base64.b64decode(ART); img=cv2.imdecode(np.frombuffer(raw,np.uint8),cv2.IMREAD_COLOR)
        self.rgb=cv2.cvtColor(cv2.resize(img,(600,400)),cv2.COLOR_BGR2RGB)
        self.y,self.x=np.mgrid[0:400,0:600].astype(np.float32)
        # Landmarks calibrated to embedded portrait; replace together with artwork.
        self.mx,self.my=289.,242.; self.eyes=[(258.,146.),(345.,157.)]
        self.mouth=np.exp(-(((self.x-self.mx)/46)**2+((self.y-self.my)/27)**2)*2)
        self.head=np.exp(-(((self.x-300)/190)**2+((self.y-195)/220)**2))
        self.eye_masks=[np.exp(-(((self.x-x)/27)**2+((self.y-y)/12)**2)*2) for x,y in self.eyes]
        self.t0=time.monotonic(); self.next_blink=2.8; self.level=0.; self.width_scale=1.; self.target=0.; self.viseme=None
        self.demo=False; self.paused=False; self.reduced=False; self.frame=QImage(); self.tick()
        self.timer=QTimer(self); self.timer.setTimerType(Qt.TimerType.PreciseTimer); self.timer.timeout.connect(self.tick); self.timer.start(33)
    def set_level(self,level,viseme=None): self.target=max(0.,min(1.,float(level))); self.viseme=viseme
    def tick(self):
        if not self.isVisible() and not self.frame.isNull(): return
        t=time.monotonic()-self.t0
        target=self.target; wide=1.
        if self.demo: target=max(0.,math.sin(t*9)*.45+math.sin(t*15)*.2+.25)
        if self.viseme in VISEMES: target,wide=VISEMES[self.viseme]
        if self.paused: target=0.
        self.level+=(target-self.level)*.35; self.width_scale+=(wide-self.width_scale)*.3
        if self.reduced:
            self.frame=QImage(self.rgb.data,600,400,1800,QImage.Format.Format_RGB888).copy(); self.update(); return
        if t>self.next_blink+.22: self.next_blink=t+3.1+1.3*(.5+.5*math.sin(t*7))
        blink=max(0.,math.sin((t-self.next_blink)/.22*math.pi)) if self.next_blink<=t<=self.next_blink+.22 else 0.
        # Inverse smooth local warp, baseline mouth compressed at silence.
        vertical=.48+1.05*self.level
        mapx=self.x+(self.x-self.mx)*(1/self.width_scale-1)*self.mouth
        mapy=self.y+(self.y-self.my)*(1/vertical-1)*self.mouth
        for (ex,ey),mask in zip(self.eyes,self.eye_masks):
            mapy=mapy+(self.y-ey)*blink*3.2*mask
        mapx=mapx+math.sin(t*.65)*2.1*self.head
        mapy=mapy+math.sin(t*.85)*1.6*self.head
        out=cv2.remap(self.rgb,mapx.astype(np.float32),mapy.astype(np.float32),cv2.INTER_LINEAR,borderMode=cv2.BORDER_REFLECT)
        self.frame=QImage(out.data,600,400,1800,QImage.Format.Format_RGB888).copy(); self.update()
    def paintEvent(self,event):
        p=QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing); p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        p.fillRect(self.rect(),QColor('#19171e'))
        scale=min(self.width()/600,self.height()/400); w,h=600*scale,400*scale
        p.drawImage(QRectF((self.width()-w)/2,(self.height()-h)/2,w,h),self.frame)
        if not self.reduced:
            t=time.monotonic()-self.t0
            for i in range(28):
                x=self.width()*(.12+.76*((i*.618)%1)); y=self.height()*(.15+.7*((i*.317)%1))+math.sin(t+i)*4
                p.setPen(Qt.PenStyle.NoPen); p.setBrush(QColor(208,188,255,int((25+65*self.level)*(.5+.5*math.sin(t*1.5+i)))))
                p.drawEllipse(QPointF(x,y),1.1,1.1)

class AudioAnalysis:
    @staticmethod
    def read(path):
        if Path(path).stat().st_size>64*1024*1024: raise ValueError('Áudio maior que 64 MB.')
        with wave.open(str(path),'rb') as f:
            if f.getsampwidth()!=2 or f.getnchannels() not in (1,2) or f.getcomptype()!='NONE':
                raise ValueError('Use WAV PCM de 16 bits, mono ou estéreo.')
            rate=f.getframerate(); n=f.getnframes(); channels=f.getnchannels()
            if n/rate>120: raise ValueError('O preview aceita até 120 segundos por áudio.')
            samples=np.frombuffer(f.readframes(n),dtype='<i2').astype(np.float32)/32768
        if not len(samples): raise ValueError('Áudio vazio.')
        samples=samples.reshape(-1,channels)
        # RMS across channels avoids cancellation of phase-inverted stereo.
        block=max(1,int(rate*.02)); energies=[]
        for i in range(0,len(samples),block): energies.append(float(np.sqrt(np.mean(samples[i:i+block]**2))))
        env=np.array(energies); norm=max(.025,float(np.percentile(env,95)))
        return np.clip((env-.008)/norm,0,1),block/rate

class VoiceView(QFrame):
    action_requested=pyqtSignal(str)
    microphone_changed=pyqtSignal(bool)
    context_changed=pyqtSignal(bool)
    analysis_ready=pyqtSignal(int,object,object,str)
    def __init__(self,parent=None):
        super().__init__(parent); self.setObjectName('root'); self.setMinimumSize(520,860)
        self.setStyleSheet('''QFrame#root {background:#141218;border-radius:30px;}
        QFrame#card {background:#211e27;border-radius:24px;} QLabel{color:#f7f4ff;background:transparent;}
        QMenu{background:#302b3a;color:#f7f4ff;padding:8px;} QMenu::item:selected{background:#56466d;}
        ''')
        self.executor=ThreadPoolExecutor(max_workers=1); self.generation=0; self.env=None; self.step=.02; self.cues=[]
        self.external_at=0.; self.context=False
        self.player=QMediaPlayer(self); self.output=QAudioOutput(self); self.player.setAudioOutput(self.output)
        self.player.errorOccurred.connect(lambda e,s:self.set_status('Erro de áudio: '+s))
        self.analysis_ready.connect(self._loaded)
        root=QVBoxLayout(self); root.setContentsMargins(14,14,14,14); root.setSpacing(10)
        head=self.card(); h=QHBoxLayout(head); h.setContentsMargins(14,12,14,12)
        logo=MotionButton('wave',primary=True); logo.setFixedWidth(50); h.addWidget(logo)
        names=QVBoxLayout(); title=QLabel('Hanauta AI'); title.setFont(QFont('Sans Serif',20,QFont.Weight.DemiBold)); names.addWidget(title)
        self.status=QLabel('Modo de voz · Pronta'); self.status.setStyleSheet('color:#c4b4e2'); names.addWidget(self.status); h.addLayout(names,1)
        for glyph,action in [('clock','history'),('settings','settings'),('close','close')]:
            b=MotionButton(glyph); b.setFixedWidth(48); h.addWidget(b); b.clicked.connect(lambda checked=False,a=action:self.action(a))
        root.addWidget(head)
        tabs=QHBoxLayout(); convo=MotionButton('chat','Conversa'); convo.clicked.connect(lambda:self.action('conversation')); tabs.addWidget(convo)
        voice=MotionButton('wave','Voz',True); tabs.addWidget(voice); root.addLayout(tabs)
        body=self.card(); body.setMinimumHeight(415); layout=QVBoxLayout(body); layout.setContentsMargins(10,10,10,10); layout.setSpacing(8)
        self.mode=QLabel('  YUNA · AGUARDANDO ÁUDIO'); self.mode.setStyleSheet('color:#d0bcff;font-size:11px;'); layout.addWidget(self.mode)
        self.face=FaceCanvas(); layout.addWidget(self.face,1)
        self.user_text=self.transcript(layout,'VOCÊ','Me ajuda a organizar meu dia?',False)
        self.ai_text=self.transcript(layout,'HANAUTA','Claro, Gabi. Vamos começar pelo que é mais importante para você hoje.',True)
        root.addWidget(body,1)
        self.context_button=MotionButton('screen','Contexto da tela · Desativado'); self.context_button.setFixedHeight(64)
        self.context_button.clicked.connect(self.toggle_context); root.addWidget(self.context_button)
        actions=QHBoxLayout()
        self.mute=MotionButton('speaker','Silenciar'); self.mute.setCheckable(True); self.mute.toggled.connect(self.set_muted)
        self.pause=MotionButton('pause','Pausar'); self.pause.setCheckable(True); self.pause.toggled.connect(self.set_paused)
        self.mic=MotionButton('mic','Microfone',True); self.mic.setCheckable(True); self.mic.toggled.connect(self.toggle_mic)
        end=MotionButton('phone','Encerrar',danger=True); end.clicked.connect(self.end_call)
        keyboard=MotionButton('keyboard','Teclado'); keyboard.clicked.connect(lambda:self.action('keyboard'))
        for b in (self.mute,self.pause,self.mic,end,keyboard): actions.addWidget(b)
        root.addLayout(actions)
        extras=QHBoxLayout()
        for glyph,label,a in [('attach','Anexar','attach'),('screen','Capturar tela','capture'),('settings','Configurar','settings')]:
            b=MotionButton(glyph,label); b.clicked.connect(lambda checked=False,a=a:self.action(a)); extras.addWidget(b)
        root.addLayout(extras)
        self.sync=QTimer(self); self.sync.timeout.connect(self.sync_audio); self.sync.start(33)
    @staticmethod
    def card():
        f=QFrame(); f.setObjectName('card'); return f
    def transcript(self,layout,name,text,primary):
        f=QFrame(); f.setStyleSheet('QFrame{background:'+ (ACCENT if primary else RAISED)+';border-radius:19px;}')
        v=QVBoxLayout(f); v.setContentsMargins(18,10,18,12); v.setSpacing(4)
        label=QLabel(name); label.setStyleSheet('color:'+ (INK if primary else ACCENT)+';font-size:10px;'); v.addWidget(label)
        t=QLabel(text); t.setTextFormat(Qt.TextFormat.PlainText); t.setWordWrap(True); t.setStyleSheet('color:'+(INK if primary else '#f7f4ff')+';font-size:14px;'); v.addWidget(t); layout.addWidget(f); return t
    def set_transcripts(self,user,assistant): self.user_text.setText(user); self.ai_text.setText(assistant)
    def set_status(self,text): self.status.setText(text); self.status.setToolTip(text)
    def action(self,a):
        self.action_requested.emit(a)
        if a=='settings': self.settings_menu()
    def toggle_context(self):
        self.context=not self.context; self.context_button.caption='Contexto da tela · '+('Ativado' if self.context else 'Desativado'); self.context_button.update(); self.context_changed.emit(self.context)
    def toggle_mic(self,on):
        self.mic.caption='Mic ativo' if on else 'Microfone'; self.microphone_changed.emit(on); self.action_requested.emit('microphone_on' if on else 'microphone_off')
    def set_muted(self,on):
        self.output.setMuted(on); self.mute.caption='Mudo' if on else 'Silenciar'; self.action_requested.emit('mute' if on else 'unmute')
    def set_paused(self,on):
        self.face.paused=on; self.pause.glyph='play' if on else 'pause'; self.pause.caption='Retomar' if on else 'Pausar'
        if on: self.player.pause()
        elif self.env is not None: self.player.play()
        self.action_requested.emit('pause' if on else 'resume')
    def set_visemes(self,cues):
        checked=[]; end=0.
        for cue in cues:
            s,e,v=float(cue['start']),float(cue['end']),str(cue['value']).upper()
            if not (math.isfinite(s) and math.isfinite(e) and 0<=s<e and s>=end and v in VISEMES):
                raise ValueError('Visemas inválidos: use intervalos ordenados sem sobreposição, A–H ou X.')
            checked.append((s,e,v)); end=e
        self.cues=checked
    def play_wav(self,path,cues=None):
        self.stop(); self.set_visemes(cues or []); self.set_status('Preparando áudio…'); self.mode.setText('  ANALISANDO ÁUDIO')
        generation=self.generation; filename=str(Path(path).resolve()); future=self.executor.submit(AudioAnalysis.read,filename)
        def done(f):
            try: data=f.result(); error=''
            except Exception as exc: data=None; error=str(exc)
            try: self.analysis_ready.emit(generation,filename,data,error)
            except RuntimeError: pass
        future.add_done_callback(done)
    def _loaded(self,generation,path,data,error):
        if generation!=self.generation:return
        if error:self.set_status(error); self.mode.setText('  ÁUDIO NÃO CARREGADO'); return
        self.env,self.step=data; self.pause.setChecked(False); self.face.demo=False
        self.player.setSource(QUrl.fromLocalFile(path)); self.player.play(); self.set_status('Modo de voz · Áudio local')
    def set_voice_frame(self,level,viseme=None):
        self.face.demo=False; self.external_at=time.monotonic(); self.face.set_level(level,viseme); self.mode.setText('  HANAUTA ESTÁ FALANDO · TTS EXTERNO')
    def sync_audio(self):
        if self.player.playbackState()==QMediaPlayer.PlaybackState.PlayingState and self.env is not None:
            t=self.player.position()/1000; i=int(t/self.step); level=float(self.env[i]) if i<len(self.env) else 0.
            v=next((v for s,e,v in self.cues if s<=t<e),None)
            self.face.set_level(level,v); self.mode.setText('  HANAUTA ESTÁ FALANDO · '+('VISEMAS' if self.cues else 'ÁUDIO'))
        elif not self.face.demo and time.monotonic()-self.external_at>.25:
            self.face.set_level(0); self.mode.setText('  YUNA · '+('PAUSADA' if self.face.paused else 'AGUARDANDO ÁUDIO'))
    def stop(self):
        self.generation+=1; self.player.stop(); self.env=None; self.cues=[]; self.external_at=0
        self.face.demo=False; self.face.set_level(0); self.pause.setChecked(False)
    def end_call(self):
        self.stop(); self.mic.setChecked(False); self.set_status('Modo de voz · Encerrado'); self.action_requested.emit('end')
    def settings_menu(self):
        menu=QMenu(self); load=menu.addAction('Abrir áudio WAV…'); cues=menu.addAction('Carregar visemas JSON…')
        demo=menu.addAction('Demonstração de movimento (sem áudio)'); reduce=menu.addAction('Reduzir movimentos'); reduce.setCheckable(True); reduce.setChecked(self.face.reduced)
        selected=menu.exec(self.mapToGlobal(self.rect().center()))
        if selected==load:
            filename,_=QFileDialog.getOpenFileName(self,'Áudio da voz','','WAV (*.wav)')
            if filename:self.play_wav(filename)
        elif selected==cues:
            filename,_=QFileDialog.getOpenFileName(self,'Visemas temporizados','','JSON (*.json)')
            if filename:
                try:
                    data=json.loads(Path(filename).read_text()); self.set_visemes(data['mouthCues']); self.set_status('Visemas carregados')
                except Exception as exc: QMessageBox.warning(self,'Visemas',str(exc))
        elif selected==demo:
            self.stop(); self.face.demo=True; self.mode.setText('  DEMONSTRAÇÃO VISUAL · SEM ÁUDIO'); self.set_status('Modo de voz · Demonstração')
        elif selected==reduce: self.face.reduced=reduce.isChecked()
    def closeEvent(self,event):
        self.stop(); self.executor.shutdown(wait=False,cancel_futures=True); super().closeEvent(event)

class VoiceWindow(QWidget):
    def __init__(self):
        super().__init__(); self.setWindowTitle('Hanauta · Holographic Yuna'); self.resize(610,930)
        self.setStyleSheet('background:#141218;'); layout=QVBoxLayout(self); layout.setContentsMargins(0,0,0,0)
        self.view=VoiceView(); layout.addWidget(self.view); self.view.action_requested.connect(self.handle)
    def handle(self,action):
        if action=='close':self.close()
        elif action not in ('settings','pause','resume','mute','unmute','end'):
            self.view.set_status('Integração Hanauta · '+action)
    def closeEvent(self,event): self.view.close(); super().closeEvent(event)

def main():
    parser=argparse.ArgumentParser(description=__doc__); parser.add_argument('--wav'); parser.add_argument('--cues'); parser.add_argument('--demo',action='store_true'); args=parser.parse_args()
    app=QApplication(sys.argv[:1]); app.setFont(QFont('Sans Serif',10)); win=VoiceWindow(); win.show()
    if args.wav:
        try:
            cues=json.loads(Path(args.cues).read_text())['mouthCues'] if args.cues else None
            win.view.play_wav(args.wav,cues)
        except Exception as exc: QMessageBox.warning(win,'Áudio',str(exc))
    elif args.demo: win.view.face.demo=True; win.view.mode.setText('  DEMONSTRAÇÃO VISUAL · SEM ÁUDIO')
    sys.exit(app.exec())

if __name__=='__main__':main()
